select f.forecast_id, f.event_id, f.contract_id, f.market_id, f.model_id, f.model_version, f.model_state, f.probability, f.captured_at, f.data_cutoff_at, f.market_probability, f.market_observed_at, f.market_snapshot_key, f.confidence, f.feature_snapshot_id, f.record_type, f.provenance, f.explanation, f.metadata
from pred_forecasts f where f.forecast_id in (select forecast_id from pred_forecast_designations where contract_id in (select contract_id from pred_contracts where event_type = 'MAX_TEMP_BUCKET'))
